import numpy as np
import time


def _score(h):
    h = np.asarray(h, dtype=float)
    if h.ndim != 1 or h.size == 0:
        return -1.0
    s = h.sum()
    if s <= 0 or not np.all(np.isfinite(h)):
        return -1.0
    L = np.convolve(h, h)
    M = L.max()
    if M <= 0:
        return -1.0
    Le = np.empty(L.size + 2)
    Le[0] = 0.0
    Le[-1] = 0.0
    Le[1:-1] = L
    l2 = np.sum(Le[:-1] ** 2 + Le[:-1] * Le[1:] + Le[1:] ** 2) / 3.0
    l1 = s * s
    return l2 / (l1 * M)


def _score_fast(L, s):
    Le = np.empty(L.size + 2)
    Le[0] = 0.0
    Le[-1] = 0.0
    Le[1:-1] = L
    l2 = np.sum(Le[:-1] ** 2 + Le[:-1] * Le[1:] + Le[1:] ** 2) / 3.0
    return l2 / (s * s * L.max())


def _polish(h, time_limit, rng):
    """Coordinate hill climbing, working on the symmetric half when possible."""
    h = h.copy()
    n = h.size
    best = _score(h)
    step = 0.25
    while time.process_time() < time_limit:
        improved = False
        order = rng.permutation(n)
        for i in order:
            if time.process_time() >= time_limit:
                break
            old = h[i]
            for mult in (1.0 + step, 1.0 - step):
                if mult <= 0:
                    continue
                h[i] = old * mult
                sc = _score(h)
                if sc > best + 1e-14:
                    best = sc
                    old = h[i]
                    improved = True
                else:
                    h[i] = old
        if not improved:
            step *= 0.5
            if step < 1e-5:
                break
    return h, best


def _mirror(u):
    """Build full symmetric array from a half-array."""
    return np.concatenate([u, u[::-1]])


def _score_half(u):
    return _score(_mirror(u))


def _polish_half(u, time_limit, rng):
    u = u.copy()
    best = _score_half(u)
    step = 0.25
    n = u.size
    while time.process_time() < time_limit:
        improved = False
        order = rng.permutation(n)
        for i in order:
            if time.process_time() >= time_limit:
                break
            old = u[i]
            for mult in (1.0 + step, 1.0 - step):
                if mult <= 0:
                    continue
                u[i] = old * mult
                sc = _score_half(u)
                if sc > best + 1e-14:
                    best = sc
                    old = u[i]
                    improved = True
                else:
                    u[i] = old
        if not improved:
            step *= 0.5
            if step < 1e-5:
                break
    return u, best


def construct(budget_seconds, start):
    t0 = time.process_time()
    limit = t0 + budget_seconds * 0.85
    rng = np.random.default_rng(2024)

    candidates = []
    if start is not None:
        try:
            s = np.asarray(start, dtype=float).ravel()
            if s.size > 0 and s.size <= 50000 and np.all(np.isfinite(s)) and s.sum() > 0:
                candidates.append(np.maximum(s, 0.0))
        except Exception:
            pass

    # Structured seeds: sqrt-triangle-like profiles at several sizes
    # (these give high R because f*f is flat-topped).
    for N in (201, 401, 801, 1601, 3201):
        i = np.arange(N, dtype=float)
        t = np.abs(2.0 * i / (N - 1) - 1.0)
        candidates.append(np.sqrt(np.clip(1.0 - t, 0.0, None)) + 1e-6)
        candidates.append(np.clip(1.0 - t, 0.0, None) ** 0.75 + 1e-6)

    best_h = None
    best_sc = -1.0
    for c in candidates:
        c = np.asarray(c, dtype=float)
        c = np.maximum(c, 0.0)
        if c.sum() <= 0:
            continue
        sc = _score(c)
        if sc > best_sc:
            best_sc = sc
            best_h = c.copy()

    # Prefer working on an even-length symmetric half when the best is symmetric.
    n = best_h.size
    use_half = (n % 2 == 0) and np.allclose(best_h[:n // 2], best_h[n // 2:][::-1], atol=1e-9)

    if use_half:
        u = best_h[:n // 2].copy()
        u, sc = _polish_half(u, limit, rng)
        best_h = _mirror(u)
        best_sc = sc
    else:
        # Try to symmetrise: average with reverse.
        sym = 0.5 * (best_h + best_h[::-1])
        if sym.sum() > 0:
            sc = _score(sym)
            if sc >= best_sc - 1e-9:
                best_h = sym
                best_sc = sc
        best_h, best_sc = _polish(best_h, limit, rng)

    # If time remains and shape is even, snap to symmetric half and re-polish.
    if time.process_time() < limit:
        n = best_h.size
        if n % 2 == 0:
            u = best_h[:n // 2].copy()
            u, sc = _polish_half(u, limit, rng)
            if sc > best_sc:
                best_h = _mirror(u)
                best_sc = sc
        else:
            best_h, best_sc = _polish(best_h, limit, rng)

    return np.maximum(np.asarray(best_h, dtype=float), 0.0)
